// Evidence guard. A generated 'after' frame in a proof cut is fabricated evidence — a
// compliance failure in services and health, not a stylistic choice. The pair must be
// marked as real captures upstream or this render refuses to run.
const pair = $json.payload.evidence_pair;
if (!pair || pair.generated === true) {
  throw new Error('COMPLIANCE_BLOCKED: before/after proof requires captured (not generated) frames');
}
